CREATE OR ALTER PROCEDURE [dbo].[GetSiteNavigationCounts] ( @ResourceId int ) AS BEGIN
declare @cntdata int = 0;
drop table if exists #temtable;
select a.AssetID, a.assettypeid into #temtable from [dbo].[AssetWithAssetsByTypeUserCantRead](@ResourceID) a
create index idx_temtable_asset_type on #temtable (AssetID, assettypeid);
select @cntdata = count(1) from #temtable;
if (@cntdata = 0) SELECT ATT.Uid, ATT.Name, 1 as count FROM AssetType ATT WHERE EXISTS ( SELECT 1 FROM Asset A WHERE A.AssetTypeID = ATT.id AND ATT.Class IN ( 1, 2, 6, 7, 8 ) ) ORDER BY ATT.Name; else SELECT ATT.Uid, ATT.Name, 1 as count FROM AssetType ATT WHERE EXISTS ( SELECT 1 FROM Asset A WHERE A.AssetTypeID = ATT.id AND ATT.Class IN ( 1, 2, 6, 7, 8 ) AND not exists (SELECT 1 FROM #temtable rd where rd.assetid = A.id and rd.assettypeid = A.assettypeid) ) ORDER BY ATT.Name;
END GO
